  1 │ package hu.bankmonitor.payments.transfers;
  2 │ 
  3 │ import hu.bankmonitor.payments.common.ProblemType;
  4 │ import hu.bankmonitor.payments.transfers.checks.Check;
  5 │ import hu.bankmonitor.payments.transfers.checks.CheckNotRequiredException;
  6 │ import jakarta.validation.Valid;
  7 │ import org.springframework.http.HttpStatus;
  8 │ import org.springframework.http.ProblemDetail;
  9 │ import org.springframework.web.bind.annotation.ExceptionHandler;
 10 │ import org.springframework.web.bind.annotation.PathVariable;
 11 │ import org.springframework.web.bind.annotation.PostMapping;
 12 │ import org.springframework.web.bind.annotation.RequestBody;
 13 │ import org.springframework.web.bind.annotation.RequestMapping;
 14 │ import org.springframework.web.bind.annotation.RestController;
 15 │ 
 16 │ /**
 17 │  * The inbound callback a Check service — or a human approver's back-office tool — reports a
 18 │  * Verdict through.
 19 │  *
 20 │  * <p><b>A thin adapter over {@link VerdictRecording#recordVerdict} and nothing else.</b> It
 21 │  * decides no part of a Transfer's lifecycle: the reading of the ledger, the money and the
 22 │  * status all happen under the row lock in one transaction the domain owns, and what is left
 23 │  * here is the translation between an HTTP request and that call. A broker consumer would be
 24 │  * a second adapter over the same operation, and this class is what it would resemble.
 25 │  *
 26 │  * <p><b>The asymmetry with outbound events is deliberate.</b> Outbound needs an outbox
 27 │  * because <em>we</em> own the atomicity of "the Transfer committed, therefore the event
 28 │  * exists". Inbound owns no such thing. It needs to be idempotent, and it already is: a
 29 │  * redelivered Verdict is absorbed by the ledger's guarded update, and one that arrives after
 30 │  * the Transfer finished meets {@link #handleLateVerdict} below.
 31 │  *
 32 │  * <p><b>What guards this endpoint is not in this file.</b> The shared secret is a rule about
 33 │  * the {@code /internal} prefix, enforced by the filter chain in {@code SecurityConfiguration}
 34 │  * before the dispatcher runs — so a second internal endpoint inherits it rather than having
 35 │  * to remember it, and no request that failed it can reach the code below. Design decision 10
 36 │  * has why the rule exists: an unauthenticated Verdict endpoint means anyone approves their
 37 │  * own Transfer and walks past fraud screening.
 38 │  *
 39 │  * <p>The refusal handlers sit on the controller rather than in a {@code @ControllerAdvice},
 40 │  * on {@code TransferController}'s reasoning: an advice would have to out-order
 41 │  * {@code ProblemDocumentAdvice}, whose handler for {@code Exception} would otherwise answer
 42 │  * each of them as a {@code 500}.
 43 │  */
 44 │ @RestController
 45 │ @RequestMapping(InternalVerdictController.PATH)
 46 │ class InternalVerdictController {
 47 │ 
 48 │ 	/**
 49 │ 	 * Under the prefix the security chain guards, which is what makes the mapping and the
 50 │ 	 * authorization rule agree by construction rather than by review.
 51 │ 	 */
 52 │ 	static final String PATH = "/internal/transfers";
 53 │ 
 54 │ 	private static final String CHECK_NOT_REQUIRED_DETAIL =
 55 │ 			"That Transfer's Check Ledger has no such Check outstanding.";
 56 │ 
 57 │ 	private static final String LATE_VERDICT_DETAIL =
 58 │ 			"That Transfer has already finished, so a Verdict no longer changes it.";
 59 │ 
 60 │ 	private final VerdictRecording verdicts;
 61 │ 
 62 │ 	InternalVerdictController(VerdictRecording verdicts) {
 63 │ 		this.verdicts = verdicts;
 64 │ 	}
 65 │ 
 66 │ 	/**
 67 │ 	 * Records one Check's answer for one Transfer and answers with where the Transfer got to.
 68 │ 	 *
 69 │ 	 * <p>The Transfer and the Check are the address rather than the payload, so the URL names
 70 │ 	 * exactly the one outstanding ledger row being answered — design decision 9's shape,
 71 │ 	 * unchanged.
 72 │ 	 *
 73 │ 	 * <p><b>{@code 200} rather than {@code 201} or {@code 204}.</b> Nothing is created at a
 74 │ 	 * URL a caller could then fetch, and there is something to say: the status in
 75 │ 	 * {@link VerdictReceipt} is how an at-least-once reporter learns whether its Verdict was
 76 │ 	 * the last word. A {@code 204} would leave a Check service unable to tell "recorded, still
 77 │ 	 * waiting" from "recorded, and the money moved" without polling the Transfer back.
 78 │ 	 */
 79 │ 	@PostMapping("/{transferId}/checks/{check}")
 80 │ 	VerdictReceipt reportVerdict(@PathVariable long transferId, @PathVariable Check check,
 81 │ 			@Valid @RequestBody VerdictReport report) {
 82 │ 		return new VerdictReceipt(transferId, check, report.verdict(),
 83 │ 				verdicts.recordVerdict(transferId, check, report.verdict()));
 84 │ 	}
 85 │ 
 86 │ 	/** Shared with {@code TransferController}, because it is one rule about one fact. */
 87 │ 	@ExceptionHandler
 88 │ 	ProblemDetail handleUnknownTransfer(UnknownTransferException refusal) {
 89 │ 		return TransferProblems.unknownTransfer(refusal);
 90 │ 	}
 91 │ 
 92 │ 	/**
 93 │ 	 * A Check the Transfer's ledger has no row for: a reporting service running against stale
 94 │ 	 * configuration, or the right Verdict sent to the wrong Transfer. The same {@code 404} as
 95 │ 	 * an unknown Transfer, because the pair <em>is</em> the path and this pair addresses
 96 │ 	 * nothing — but under a URN of its own, because design decision 18 makes the URN the only
 97 │ 	 * member a client may branch on. Sharing {@code not-found} would leave the two told apart
 98 │ 	 * by which properties happened to be present, which is branching on something else.
 99 │ 	 *
100 │ 	 * <p>Both halves are on the wire because neither is recoverable from the other, and the
101 │ 	 * useful answer to "why was this refused" names the pair.
102 │ 	 */
103 │ 	@ExceptionHandler
104 │ 	ProblemDetail handleCheckNotRequired(CheckNotRequiredException refusal) {
105 │ 		ProblemDetail problem = TransferProblems.of(
106 │ 				HttpStatus.NOT_FOUND, ProblemType.CHECK_NOT_REQUIRED, CHECK_NOT_REQUIRED_DETAIL);
107 │ 		problem.setProperty("transferId", refusal.getTransferId());
108 │ 		problem.setProperty("check", refusal.getCheck());
109 │ 		return problem;
110 │ 	}
111 │ 
112 │ 	/**
113 │ 	 * A Verdict that arrived after the Transfer finished. {@code 409}, because the request is
114 │ 	 * well-formed and understood and it is the Transfer's state that refuses it — the same
115 │ 	 * reading of the status the two idempotency conflicts use, and the reason this needs a URN
116 │ 	 * of its own to be told apart from them.
117 │ 	 *
118 │ 	 * <p><b>It carries the status the Transfer had already reached</b>, which is what turns a
119 │ 	 * refusal into news: a Check service redelivering the Verdict that settled a Transfer
120 │ 	 * learns its report landed, and one answering a Transfer the reaper expired learns it did
121 │ 	 * not.
122 │ 	 *
123 │ 	 * <p>No {@code Retry-After}, and its absence is the machine-readable half of the refusal
124 │ 	 * on {@code TransferController}'s precedent: a Transfer never leaves a terminal status, so
125 │ 	 * a caller that retried this would retry for ever.
126 │ 	 */
127 │ 	@ExceptionHandler
128 │ 	ProblemDetail handleLateVerdict(TransferNotPendingException refusal) {
129 │ 		ProblemDetail problem = TransferProblems.of(
130 │ 				HttpStatus.CONFLICT, ProblemType.TRANSFER_NOT_PENDING, LATE_VERDICT_DETAIL);
131 │ 		problem.setProperty("transferId", refusal.getTransferId());
132 │ 		problem.setProperty("transferStatus", refusal.getStatus());
133 │ 		return problem;
134 │ 	}
135 │ }
