 1 │ package hu.bankmonitor.payments.transfers;
 2 │ 
 3 │ import hu.bankmonitor.payments.transfers.checks.Check;
 4 │ import hu.bankmonitor.payments.transfers.checks.Verdict;
 5 │ import io.swagger.v3.oas.annotations.media.Schema;
 6 │ 
 7 │ /**
 8 │  * What a Check service is told once its Verdict has been recorded: the report it made, and
 9 │  * where the Transfer got to as a result.
10 │  *
11 │  * <p><b>{@code transferStatus} is the whole point of answering with a body at all.</b> A
12 │  * Check service that reports one of two Checks learns its Verdict is not yet the last word;
13 │  * one that reports the last learns that money moved. It is the same member
14 │  * {@link TransferNotPendingException} puts on the wire when the report was too late, so
15 │  * "where is this Transfer now" is answered in one vocabulary whether the report landed or
16 │  * was refused.
17 │  *
18 │  * <p>The report is echoed back rather than assumed, because this endpoint is called by
19 │  * machines with retries and logs: a receipt that named only a status would not say which of
20 │  * several in-flight reports it was the receipt for.
21 │  *
22 │  * <p>Every member is listed as required for {@code TransferResponse}'s reason — springdoc
23 │  * derives {@code required} from constraint annotations, and a response is never validated.
24 │  */
25 │ @Schema(requiredProperties = {"transferId", "check", "verdict", "transferStatus"})
26 │ record VerdictReceipt(long transferId, Check check, Verdict verdict, TransferStatus transferStatus) {
27 │ }
