 1 │ package hu.bankmonitor.payments.transfers;
 2 │ 
 3 │ import hu.bankmonitor.payments.common.ProblemType;
 4 │ import org.springframework.http.HttpStatus;
 5 │ import org.springframework.http.ProblemDetail;
 6 │ 
 7 │ /**
 8 │  * The problem documents more than one endpoint in this slice answers with.
 9 │  *
10 │  * <p>It exists because {@link UnknownTransferException} is now raised on two paths — a
11 │  * Transfer fetched by a client and a Verdict reported by a Check service — and what status
12 │  * that fact earns is one decision, not two. Two controllers each writing their own
13 │  * {@code 404} would be two copies of the rule, and the copy that was not edited would be the
14 │  * one a client had trusted.
15 │  *
16 │  * <p>What is <em>not</em> here is every other refusal: those belong to the one endpoint that
17 │  * can meet them, on the controller that raises them, where design decision 14 put them for
18 │  * ordering reasons that have not changed. This class is a place for the shared ones and not
19 │  * a layer between a controller and its answers.
20 │  */
21 │ final class TransferProblems {
22 │ 
23 │ 	private static final String UNKNOWN_TRANSFER_DETAIL = "No Transfer has that identifier.";
24 │ 
25 │ 	private TransferProblems() {
26 │ 	}
27 │ 
28 │ 	/**
29 │ 	 * The {@code 404} ticket 05 settled, meaning <em>the path names nothing</em>. A Transfer's
30 │ 	 * identifier is its own address on both endpoints that raise this, so an identifier no
31 │ 	 * Transfer has addresses no resource — which is a different fact from ticket 14's
32 │ 	 * {@code 422} for an unknown Account named <em>inside</em> a payload.
33 │ 	 */
34 │ 	static ProblemDetail unknownTransfer(UnknownTransferException refusal) {
35 │ 		ProblemDetail problem = of(HttpStatus.NOT_FOUND, ProblemType.NOT_FOUND, UNKNOWN_TRANSFER_DETAIL);
36 │ 		problem.setProperty("transferId", refusal.getTransferId());
37 │ 		return problem;
38 │ 	}
39 │ 
40 │ 	/**
41 │ 	 * The parts every problem document in this slice shares. {@code instance} is left unset on
42 │ 	 * purpose: the message converter fills it in from the request URI for any
43 │ 	 * {@link ProblemDetail} that does not name one, so setting it here would be a second copy
44 │ 	 * of the request path to keep right.
45 │ 	 *
46 │ 	 * <p>Every {@code detail} is written by the caller rather than taken from the exception,
47 │ 	 * on {@code ProblemDocumentAdvice}'s reasoning: an exception message is written for a log.
48 │ 	 */
49 │ 	static ProblemDetail of(HttpStatus status, ProblemType type, String detail) {
50 │ 		ProblemDetail problem = ProblemDetail.forStatusAndDetail(status, detail);
51 │ 		problem.setType(type.uri());
52 │ 		return problem;
53 │ 	}
54 │ }

