40 │ 	 * no challenge to send back and no registered scheme name to send it under. A bespoke
41 │ 	 * header says what it is, and {@code X-} names the same kind of thing the Idempotency Key
42 │ 	 * header does at the other end of this API.
43 │ 	 */
44 │ 	static final String SECRET_HEADER = "X-Internal-Secret";
45 │ 
46 │ 	private final byte[] secret;
47 │ 
48 │ 	/**
