16 │ import java.io.IOException;
17 │ import java.net.URI;
18 │ 
19 │ /**
20 │  * Answers a refusal from the filter chain with the same RFC 9457 document every other error
21 │  * in this API arrives as.
22 │  *
23 │  * <p>Until the shared secret there was nothing to write this for: the chain denied paths it
24 │  * does not name, which is a caller asking for something that does not exist, and a bodiless
25 │  * {@code 403} answers that completely. The secret produces the first refusal a client is
26 │  * <em>meant to read</em> — an operator wiring up a Check service against the wrong secret —
27 │  * and a client that has learnt to parse this API's failures should not meet an empty body
28 │  * exactly where it most needs to know what happened.
29 │  *
30 │  * <p><b>The document is written here rather than by {@code ProblemDocumentAdvice}, because a
31 │  * denial never reaches the dispatcher.</b> It is raised by a filter in front of it, so no
32 │  * {@code @ControllerAdvice} can see it. Writing it through the same message converter Spring
33 │  * MVC uses is what keeps the two shapes identical rather than merely similar.
34 │  *
35 │  * <p><b>{@code 403} rather than {@code 401}</b>, for missing and wrong secrets alike. RFC
36 │  * 9110 obliges a {@code 401} to carry a {@code WWW-Authenticate} challenge naming an HTTP
37 │  * authentication scheme; a shared secret in a bespoke header is not one, so the challenge
38 │  * would either be absent — making the response malformed — or name a scheme this API does not
39 │  * accept, sending a client to retry in a way that cannot work. {@code 403} claims no scheme,
40 │  * which is the honest description of the rule.
41 │  *
42 │  * <p>It implements both entry point and handler because Spring Security chooses between them
43 │  * on whether the caller is anonymous. This application authenticates nobody, so today only
44 │  * {@link #commence} runs — and the pair is written as one class so that the day something
45 │  * does authenticate, the other path is not an empty {@code 403} nobody noticed.
46 │  */
47 │ class DeniedAsAProblemDocument implements AuthenticationEntryPoint, AccessDeniedHandler {
48 │ 
49 │ 	private static final String DETAIL = "This endpoint is internal and requires a valid secret.";
50 │ 
51 │ 	private final JacksonJsonHttpMessageConverter json;
52 │ 
53 │ 	DeniedAsAProblemDocument(JacksonJsonHttpMessageConverter json) {
54 │ 		this.json = json;
55 │ 	}
56 │ 
57 │ 	@Override
58 │ 	public void commence(HttpServletRequest request, HttpServletResponse response,
59 │ 			AuthenticationException denial) throws IOException {
60 │ 		write(request, response);
61 │ 	}
62 │ 
63 │ 	@Override
64 │ 	public void handle(HttpServletRequest request, HttpServletResponse response,
65 │ 			AccessDeniedException denial) throws IOException {
66 │ 		write(request, response);
67 │ 	}
68 │ 
69 │ 	/**
70 │ 	 * The refusal carries no property naming what was wrong with the credential, and the
71 │ 	 * {@code detail} is one sentence that reads the same whether a secret was absent, stale or
72 │ 	 * meant for another service. That uniformity is the rule rather than an economy: a
73 │ 	 * response that distinguished them would answer a caller probing for the header.
74 │ 	 *
75 │ 	 * <p>{@code instance} is set here, unlike everywhere else in this application, because the
76 │ 	 * converter that fills it in from the request URI is Spring MVC's return-value handling —
77 │ 	 * which a denial, raised before the dispatcher, never reaches.
78 │ 	 */
79 │ 	private void write(HttpServletRequest request, HttpServletResponse response) throws IOException {
80 │ 		ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.FORBIDDEN, DETAIL);
81 │ 		problem.setType(ProblemType.FORBIDDEN.uri());
82 │ 		problem.setInstance(URI.create(request.getRequestURI()));
83 │ 
84 │ 		response.setStatus(HttpStatus.FORBIDDEN.value());
85 │ 		json.write(problem, MediaType.APPLICATION_PROBLEM_JSON, new ServletServerHttpResponse(response));
86 │ 	}
87 │ }

