 33 │ /**
 34 │  * What a Check service posts to report a Verdict, what it gets back, and what happens to a
 35 │  * caller that cannot prove it is one.
 36 │  *
 37 │  * <p>No database: {@link VerdictRecording} is stubbed, so every assertion here is about the
 38 │  * wire. That the same call really settles a Transfer is
 39 │  * {@link ReportedVerdictsSettleTheTransferOverHttpTest}'s claim.
 40 │  *
 41 │  * <p><b>The filters are left on</b>, unlike {@link TransferRequestContractTest}, and that is
 42 │  * the whole reason this class imports {@link SecurityConfiguration}: the shared secret is
 43 │  * enforced by the filter chain rather than by the controller, so a slice test that disabled
 44 │  * the filters would assert the mapping and silently drop the one authorization rule this
 45 │  * application has.
 46 │  */
 47 │ @WebMvcTest(InternalVerdictController.class)
 48 │ @Import(SecurityConfiguration.class)
 49 │ class InternalVerdictContractTest {
 50 │ 
 51 │ 	private static final long TRANSFER = 31L;
 52 │ 
 53 │ 	/**
 54 │ 	 * The header and the path below are written out here rather than read from the production
 55 │ 	 * constants, on {@code TransferController}'s reasoning: a test reading the same constant
 56 │ 	 * as the thing under test follows a rename silently instead of failing on it. Both are
 57 │ 	 * part of the contract a Check service is configured against.
 58 │ 	 */
 59 │ 	private static final String SECRET_HEADER = "X-Internal-Secret";
 60 │ 
 61 │ 	private static final String APPROVAL = """
 62 │ 			{"verdict": "APPROVED"}""";
 63 │ 
 64 │ 	@Autowired
 65 │ 	private MockMvcTester mvc;
 66 │ 
 67 │ 	@MockitoBean
 68 │ 	private VerdictRecording verdicts;
 69 │ 
 70 │ 	@Value("${payments.internal.shared-secret}")
 71 │ 	private String secret;
 72 │ 
 73 │ 	@Test
 74 │ 	@DisplayName("a Verdict reported with the secret is recorded and answered with where the Transfer got to")
 75 │ 	void recordsTheVerdictAndAnswersWithTheTransfersNewStatus() {
 76 │ 		given(verdicts.recordVerdict(TRANSFER, FRAUD, APPROVED)).willReturn(TransferStatus.SETTLED);
 77 │ 
 78 │ 		MvcTestResult result = report(TRANSFER, FRAUD, APPROVAL);
 79 │ 
 80 │ 		assertThat(result).hasStatus(HttpStatus.OK);
 81 │ 		assertThat(result).hasContentTypeCompatibleWith(MediaType.APPLICATION_JSON);
 82 │ 		assertThat(result).bodyJson().extractingPath("$.transferId").isEqualTo(31);
 83 │ 		assertThat(result).bodyJson().extractingPath("$.check").isEqualTo("FRAUD");
 84 │ 		assertThat(result).bodyJson().extractingPath("$.verdict").isEqualTo("APPROVED");
 85 │ 		assertThat(result).bodyJson().extractingPath("$.transferStatus").isEqualTo("SETTLED");
 86 │ 	}
 87 │ 
 88 │ 	/**
 89 │ 	 * The Transfer is still {@code PENDING} while another Check is outstanding, and the
 90 │ 	 * caller is told so rather than being answered as though nothing had happened. It is the
 91 │ 	 * same {@code 200}: the report landed either way, and where the Transfer got to is the
 92 │ 	 * news.
 93 │ 	 */
 94 │ 	@Test
 95 │ 	@DisplayName("a Verdict that leaves other Checks outstanding answers PENDING")
 96 │ 	void answersPendingWhileAnotherCheckIsOutstanding() {
 97 │ 		given(verdicts.recordVerdict(TRANSFER, FRAUD, APPROVED)).willReturn(TransferStatus.PENDING);
 98 │ 
 99 │ 		assertThat(report(TRANSFER, FRAUD, APPROVAL)).bodyJson()
100 │ 				.extractingPath("$.transferStatus").isEqualTo("PENDING");
101 │ 	}
102 │ 
103 │ 	@Nested
104 │ 	@DisplayName("the shared secret")
105 │ 	class SharedSecret {
106 │ 
107 │ 		/**
108 │ 		 * Refused <em>before</em> the domain operation, which is the whole of what the rule
109 │ 		 * buys: a Verdict that reached {@link VerdictRecording} would have settled the
110 │ 		 * Transfer whatever status the caller was answered with afterwards.
111 │ 		 */
112 │ 		@Test
113 │ 		@DisplayName("a request with no secret never reaches the domain operation")
114 │ 		void refusesARequestWithNoSecretBeforeRecordingAnything() {
115 │ 			MvcTestResult result = mvc.post().uri(path(TRANSFER, FRAUD))
116 │ 					.contentType(MediaType.APPLICATION_JSON)
117 │ 					.content(APPROVAL)
118 │ 					.exchange();
119 │ 
120 │ 			assertThat(result).hasStatus(HttpStatus.FORBIDDEN);
121 │ 			assertThatIsAProblemDocument(result, ProblemType.FORBIDDEN);
122 │ 			then(verdicts).should(never()).recordVerdict(anyLong(), any(), any());
123 │ 		}
124 │ 
125 │ 		@Test
126 │ 		@DisplayName("a request with the wrong secret is refused the same way")
127 │ 		void refusesARequestWithTheWrongSecret() {
128 │ 			MvcTestResult result = mvc.post().uri(path(TRANSFER, FRAUD))
129 │ 					.header(SECRET_HEADER, "not-the-secret")
130 │ 					.contentType(MediaType.APPLICATION_JSON)
131 │ 					.content(APPROVAL)
132 │ 					.exchange();
133 │ 
134 │ 			assertThat(result).hasStatus(HttpStatus.FORBIDDEN);
135 │ 			assertThatIsAProblemDocument(result, ProblemType.FORBIDDEN);
136 │ 			then(verdicts).should(never()).recordVerdict(anyLong(), any(), any());
137 │ 		}
138 │ 
139 │ 		/**
140 │ 		 * A wrong secret and a missing one are answered identically, down to the wording. A
141 │ 		 * refusal that said which of the two had happened would tell a caller probing the
142 │ 		 * endpoint whether the header it guessed at is the one being checked.
143 │ 		 */
144 │ 		@Test
145 │ 		@DisplayName("a wrong secret and a missing one are indistinguishable")
146 │ 		void answersAWrongSecretExactlyAsItAnswersAMissingOne() {
147 │ 			MvcTestResult missing = mvc.post().uri(path(TRANSFER, FRAUD))
148 │ 					.contentType(MediaType.APPLICATION_JSON).content(APPROVAL).exchange();
149 │ 			MvcTestResult wrong = mvc.post().uri(path(TRANSFER, FRAUD))
150 │ 					.header(SECRET_HEADER, "not-the-secret")
151 │ 					.contentType(MediaType.APPLICATION_JSON).content(APPROVAL).exchange();
152 │ 
153 │ 			assertThat(wrong.getResponse().getContentAsString())
154 │ 					.isEqualTo(missing.getResponse().getContentAsString());
155 │ 		}
156 │ 
157 │ 		/**
158 │ 		 * The secret guards the prefix rather than the one handler under it, so a path
159 │ 		 * {@code /internal} has no endpoint at is refused before the dispatcher can say so.
160 │ 		 * Without that the rule would have to be repeated on every internal endpoint added
161 │ 		 * later, and the one that forgot would be open.
162 │ 		 */
163 │ 		@Test
164 │ 		@DisplayName("the whole internal prefix is behind the secret, not just this endpoint")
165 │ 		void guardsThePrefixRatherThanTheHandler() {
166 │ 			assertThat(mvc.get().uri("/internal/not-an-endpoint").exchange())
167 │ 					.hasStatus(HttpStatus.FORBIDDEN);
168 │ 		}
169 │ 	}
170 │ 
171 │ 	@Nested
172 │ 	@DisplayName("refusals from the domain operation")
173 │ 	class Refusals {
174 │ 
